<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Products';$msg='';$err='';
$categories=$pdo->query('SELECT category_id,name FROM categories ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);
 try{
  if($action==='save'){
   $name=trim($_POST['product_name']??'');$sku=trim($_POST['sku_code']??'');$cat=(int)$_POST['category_id'];$price=(float)$_POST['unit_price'];$compare=(float)($_POST['compare_at_price']??0);$cost=(float)($_POST['cost_price']??0);$stock=max(0,(int)$_POST['quantity_in_stock']);$reorder=max(0,(int)$_POST['reorder_level']);$brand=trim($_POST['brand']??'');$image=trim($_POST['image_url']??'');$desc=trim($_POST['description']??'');$status=in_array($_POST['status']??'ACTIVE',['ACTIVE','INACTIVE'],true)?$_POST['status']:'ACTIVE';$featured=!empty($_POST['is_featured'])?1:0;
   if($id){$pdo->prepare('UPDATE products SET sku_code=?,product_name=?,quantity_in_stock=?,reorder_level=?,unit_price=?,cost_price=?,category_id=?,status=?,image_url=?,compare_at_price=?,brand=?,is_featured=?,description=? WHERE product_id=?')->execute([$sku,$name,$stock,$reorder,$price,$cost,$cat,$status,$image,$compare,$brand,$featured,$desc,$id]);$msg='Product updated successfully.';}else{$pdo->prepare('INSERT INTO products(sku_code,product_name,quantity_in_stock,reorder_level,unit_price,cost_price,category_id,status,image_url,compare_at_price,brand,is_featured,description) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$sku,$name,$stock,$reorder,$price,$cost,$cat,$status,$image,$compare,$brand,$featured,$desc]);$msg='Product added successfully.';}
  }elseif($action==='restock'){$q=max(0,(int)$_POST['quantity']);$pdo->prepare('UPDATE products SET quantity_in_stock=quantity_in_stock+? WHERE product_id=?')->execute([$q,$id]);$msg='Stock updated.';
  }elseif($action==='toggle'){$pdo->prepare("UPDATE products SET status=IF(status='ACTIVE','INACTIVE','ACTIVE') WHERE product_id=?")->execute([$id]);$msg='Product visibility updated.';
  }elseif($action==='stock_out'){$pdo->prepare('UPDATE products SET quantity_in_stock=0 WHERE product_id=?')->execute([$id]);$msg='Product marked OUT OF STOCK. The customer storefront and carts now update from live stock.';
  }elseif($action==='stock_in'){$q=max(1,(int)($_POST['quantity']??1));$pdo->prepare("UPDATE products SET quantity_in_stock=quantity_in_stock+?,status='ACTIVE' WHERE product_id=?")->execute([$q,$id]);$msg='Stock restored and product made available to customers.';
  }elseif($action==='delete'){$pdo->prepare('DELETE FROM products WHERE product_id=?')->execute([$id]);$msg='Product deleted permanently.';}
 }catch(Throwable $e){$err=$action==='delete'?'This product cannot be permanently deleted because it is referenced by an existing order. Hide it instead.':'Could not save the product. Check that the SKU is unique and all fields are valid.';}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE product_id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.category_id=p.category_id ORDER BY p.product_id DESC')->fetchAll();require __DIR__.'/../includes/header.php';
?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a class="active" href="/admin/products.php">Products</a><a href="/admin/stock.php">Stock In / Stock Out</a><a href="/admin/orders.php">Orders</a><a href="/admin/customers.php">Customers</a><a href="/admin/reviews.php">Reviews</a><?php if(super_admin()): ?><a href="/admin/users.php">Admin accounts</a><?php endif; ?><a href="/">View store</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">FULL CATALOGUE CONTROL</span><h1>Products & inventory</h1><p>Add, edit, replace images, change prices, update stock, hide/renew or delete products.</p></div><a class="btn primary" href="/admin/products.php">+ Add product</a></div><?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?><?php if($err): ?><div class="errors"><?=e($err)?></div><?php endif; ?><section class="panel admin-editor"><h2><?= $edit?'Edit / replace product':'Add new product' ?></h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="product_id" value="<?=$edit['product_id']??0?>"><div class="two"><label>Product name<input name="product_name" required value="<?=e($edit['product_name']??'')?>"></label><label>SKU code<input name="sku_code" required value="<?=e($edit['sku_code']??'')?>"></label></div><div class="three"><label>Category<select name="category_id" required><?php foreach($categories as $c): ?><option value="<?=$c['category_id']?>" <?=((int)($edit['category_id']??0)===(int)$c['category_id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></label><label>Brand<input name="brand" value="<?=e($edit['brand']??'')?>"></label><label>Status<select name="status"><option <?=($edit['status']??'ACTIVE')==='ACTIVE'?'selected':''?>>ACTIVE</option><option <?=($edit['status']??'')==='INACTIVE'?'selected':''?>>INACTIVE</option></select></label></div><div class="four"><label>Price<input type="number" step="0.01" name="unit_price" required value="<?=e((string)($edit['unit_price']??0))?>"></label><label>Purchase cost<input type="number" step="0.01" min="0" name="cost_price" value="<?=e((string)($edit['cost_price']??0))?>"></label><label>Old price<input type="number" step="0.01" name="compare_at_price" value="<?=e((string)($edit['compare_at_price']??0))?>"></label><label>Stock<input type="number" min="0" name="quantity_in_stock" required value="<?=e((string)($edit['quantity_in_stock']??0))?>"></label><label>Reorder level<input type="number" min="0" name="reorder_level" value="<?=e((string)($edit['reorder_level']??5))?>"></label></div><label>Product image URL<input name="image_url" value="<?=e($edit['image_url']??'')?>" placeholder="https://... or /assets/products/item.jpg"><small>Replace the existing image by entering a new image URL/path. The customer storefront uses this same value.</small></label><label>Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label class="check"><input type="checkbox" name="is_featured" value="1" <?=!empty($edit['is_featured'])?'checked':''?>> Feature this product in Top Picks</label><div><button class="btn primary">Save product changes</button><?php if($edit): ?> <a class="btn ghost" href="/admin/products.php">Cancel edit</a><?php endif; ?></div></form></section><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Management</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['product_name'])?></strong><small><?=e($r['sku_code'])?> · <?=e($r['brand']??'')?></small></td><td><?=e($r['category_name']??'')?></td><td><?=money((float)$r['unit_price'])?></td><td><?=$r['quantity_in_stock']?></td><td><span class="status-pill <?=e(strtolower($r['status']))?>"><?=e($r['status'])?></span></td><td><div class="admin-product-actions"><a class="btn small" href="/admin/products.php?edit=<?=$r['product_id']?>">Edit / Replace</a><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="action" value="restock"><input type="hidden" name="product_id" value="<?=$r['product_id']?>"><input type="number" name="quantity" min="1" value="1"><button class="btn small">Restock</button></form><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="action" value="stock_in"><input type="hidden" name="product_id" value="<?=$r['product_id']?>"><input type="number" name="quantity" min="1" value="1"><button class="btn small stock-in-mini">Stock In</button></form><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="action" value="stock_out"><input type="hidden" name="product_id" value="<?=$r['product_id']?>"><button class="btn small stock-out-mini" <?=((int)$r['quantity_in_stock']<=0)?'disabled':''?>>Mark Out of Stock</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="product_id" value="<?=$r['product_id']?>"><button class="btn small"><?= $r['status']==='ACTIVE'?'Hide':'Renew' ?></button></form><form method="post" onsubmit="return confirm('Delete this product permanently? If it is used in an existing order, use Hide instead.')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="product_id" value="<?=$r['product_id']?>"><button class="link-danger">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php'; ?>
